-- Listage de la structure de procédure zak. cb_cleanup
DELIMITER //
CREATE PROCEDURE `cb_cleanup`()
BEGIN
    -- Marquer les commandes expirées
    UPDATE `cb_orders`
    SET `state` = 'expired'
    WHERE `state` = 'active' AND `expires_at` < NOW();

    -- Supprimer les vieux logs (> 30 jours)
    DELETE FROM `cb_logs`
    WHERE `created_at` < DATE_SUB(NOW(), INTERVAL 30 DAY);

    -- Supprimer les batches vendus (> 7 jours)
    DELETE FROM `cb_batches`
    WHERE `status` = 'sold' AND `completed_at` < DATE_SUB(NOW(), INTERVAL 7 DAY);
END//
DELIMITER ;

