-- Listage de la structure de procédure zak. RegisterBlackMarketSale
DELIMITER //
CREATE PROCEDURE `RegisterBlackMarketSale`(
    IN p_seller_id VARCHAR(60),
    IN p_seller_name VARCHAR(100),
    IN p_sample_type VARCHAR(20),
    IN p_quantity INT,
    IN p_price_per_unit INT,
    IN p_location VARCHAR(255)
)
BEGIN
    DECLARE total INT;
    SET total = p_quantity * p_price_per_unit;

        seller_identifier,
        seller_name,
        sample_type,
        quantity,
        price_per_unit,
        total_price,
        location
    ) VALUES (
        p_seller_id,
        p_seller_name,
        p_sample_type,
        p_quantity,
        p_price_per_unit,
        total,
        p_location
    );

    SELECT total as earned_amount;
END//
DELIMITER ;

-- Listage de la structure de procédure zak. RegisterSample
DELIMITER //
CREATE PROCEDURE `RegisterSample`(
    IN p_medic_id VARCHAR(60),
    IN p_medic_name VARCHAR(100),
    IN p_patient_id VARCHAR(60),
    IN p_patient_name VARCHAR(100),
    IN p_sample_type VARCHAR(20),
    IN p_is_legal TINYINT,
    IN p_location VARCHAR(255)
)
BEGIN
        medic_identifier,
        medic_name,
        patient_identifier,
        patient_name,
        sample_type,
        is_legal,
        location
    ) VALUES (
        p_medic_id,
        p_medic_name,
        p_patient_id,
        p_patient_name,
        p_sample_type,
        p_is_legal,
        p_location
    );

    SELECT LAST_INSERT_ID() as sample_id;
END//
DELIMITER ;

