INSERT INTO `company_notes` (`id`, `job`, `title`, `content`, `created_by`, `created_at`, `updated_at`) VALUES
	(5, 'joebar', 'fsfse', 'fsefse', 'Emilio Vargas', '2025-12-29 17:25:52', '2025-12-29 17:25:52'),
	(14, 'harmony', 'PARTENARIATS', '- Employés : -20% sur vos customs \n\n----------------------------------------\n\n- Up\'N\'Atom : -10%\n> Manu Lope\n> Thomas Dicon\n> Franklin Davis\n> Persee Jacker\n\n\n----------------------------------------\n\n- Concessionnaire : -7.5% (vous bénéficiez en tant qu\'employé de -10% chez lui)\n> Marc Sanson \n> Sander Van Loon\n> Kazuma kurosawa', 'Iris Marshall', '2026-01-08 16:47:22', '2026-01-10 18:35:31'),
	(15, 'harmony', 'ANNONCES OUVERTURE & FERMETURE', 'Quatres nouveaux modèles d\'annonces ont été crées.\n\nN\'hésitez pas a les utiliser pour avoir plus de visibilité !\n\n[PS : N\'oubliez pas d\'enlever votre service quand vous quitter le garage merciii]', 'Iris Marshall', '2026-01-08 16:53:56', '2026-01-08 16:53:56'),
	(16, 'upnatom', 'Nouveautés', 'Des possibilités en facture supplémentaire, merci de jetté un oeil.', 'Persee Jacker', '2026-01-09 13:41:02', '2026-01-09 13:41:02'),
	(17, 'upnatom', 'Avantage Partenaire', 'SAMS -16.8% sur les soins\nConcess -10% sur les véhicules\nOtto\'s -12% sur les customs\nHarmony -10% sur les customs\nRedwood -10% sur les commandes', 'Persee Jacker', '2026-01-09 13:42:29', '2026-01-09 13:42:29'),
	(18, 'upnatom', 'Obligation', 'Tenu de cuisine obligatoire (si vous en avez pas, merci de contacter un collègue / gérant pour vous en procurer)\nCe laver les mains avant de cuisiner\nVous finissez votre service quand vous partez\nRadio 69 pour toute communication employés / gérant.', 'Persee Jacker', '2026-01-09 13:44:50', '2026-01-09 13:44:50'),
	(19, 'auto_occaz', 'MAMA LE GITAN', 'LE NIGLOOO', 'Wyatt Blackwood', '2026-01-09 16:38:01', '2026-01-09 16:38:01'),
	(20, 'dealership', 'Entretient collectif', 'Bonjour à toute l\'équipe, je suis le nouveau gérant du concessionnaire du Nord, je prendrais le temps de me présenter ce soir 12/01/26 à 21h30, vous êtes tous conviés à un entretient collectif afin de parler de votre avenir et celui du concessionnaire. Merci de venir muni de votre carte d\'identité ainsi que de votre permis de conduire. A tout à l\'heure.', 'Enzo Teixeira', '2026-01-12 16:24:02', '2026-01-12 16:24:02');
