INSERT INTO `fishing_simulator_available_contracts` (`id`, `name`, `description`, `image`, `required_items`, `money_reward`, `item_reward`, `delivery_location`, `progress`, `timestamp`) VALUES
	(35816, 'Défi de pêche sportive', 'Attrapez ces espèces difficiles pour gagner un prix lors du concours de pêche sportive local..', 'images/deliveries/sport_fishing.png', '[{"display_name":"Requin tigre","name":"tiger_shark","amount":1},{"display_name":"Mérou géant","name":"giant_grouper","amount":1}]', 3912, NULL, '[-1097.9399999999442,-1673.3599999998697,8.40000000000145]', NULL, 1768273491),
	(35817, 'Stock d\'aquarium exotique', 'Un aquarium exotique cherche à ajouter des espèces rares à sa collection. Pouvez-vous les fournir ?', 'images/deliveries/exotic_aquarium.png', '[{"display_name":"Poisson-globe","name":"pufferfish","amount":2},{"display_name":"Anguille électrique","name":"electric_eel","amount":1}]', 6340, NULL, '[-3089.2400000002237,221.4899999999907,14.0699999999997]', NULL, 1768273495),
	(35818, 'Marché aux poissons gastronomique', 'Un marché haut de gamme recherche du poisson de première qualité. Exécutez leur commande pour un paiement généreux.', 'images/deliveries/gourmet_market.png', '[{"display_name":"Saumon sockeye","name":"sockeye_salmon","amount":2},{"display_name":"Esturgeon européen","name":"european_sea_sturgeon","amount":1}]', 3983, NULL, '[-321.94,-1545.74,31.02]', NULL, 1768273527),
	(35819, 'Recherche biologique', 'Aider les chercheurs en leur fournissant des spécimens pour leur étude de la vie aquatique.', 'images/deliveries/biological_research.png', '[{"display_name":"Raie géante d\'eau douce","name":"giant_freshwater_stingray","amount":1},{"display_name":"Dauphin rose","name":"pink_river_dolphin","amount":1}]', NULL, '{"display_name":"Advanced Research Kit","item":"research_kit","amount":1}', '[-1965.3300000000746,-296.95999999996277,41.10000000000582]', NULL, 1768273611),
	(35820, 'Don au Musée maritime', 'Le musée maritime local a besoin de spécimens pour sa nouvelle exposition sur l\'océan. Aidez-les !', 'images/deliveries/maritime_donation.png', '[{"display_name":"Thon rouge","name":"bluefin_tuna","amount":1},{"display_name":"Esturgeon blanc","name":"white_sturgeon","amount":1}]', 2422, NULL, '[-805.1399999998976,-959.5400000000373,18.12999999999738]', NULL, 1768273615),
	(35821, 'Don au Musée maritime', 'Le musée maritime local a besoin de spécimens pour sa nouvelle exposition sur l\'océan. Aidez-les !', 'images/deliveries/maritime_donation.png', '[{"display_name":"Thon rouge","name":"bluefin_tuna","amount":1},{"display_name":"Esturgeon blanc","name":"white_sturgeon","amount":1}]', 2360, NULL, '[2258.59,5165.84,59.12]', NULL, 1768273648),
	(35822, 'Commande de fourniture d\'appâts', 'Un magasin de pêche a besoin de divers poissons communs comme appât. Aidez-les à réapprovisionner leur inventaire.', 'images/deliveries/bait_supply_order.png', '[{"display_name":"Ablette commune","name":"common_bleak","amount":10},{"display_name":"Achigan à petite bouche","name":"smallmouth_bass","amount":2}]', 186, NULL, '[-374.4100000000326,6191.039999999106,31.7300000000032]', NULL, 1768273731),
	(35823, 'Collection Exotique', 'Livrez ces poissons rares pour gagner un équipement spécial!', 'images/deliveries/exotic_collection.png', '[{"display_name":"Anguille électrique","name":"electric_eel","amount":2},{"display_name":"Calmar géant","name":"giant_squid","amount":1}]', NULL, '{"item":"fishing_gear","display_name":"High-end Fishing Gear","amount":1}', '[430.1600000000326,-1559.3100000000559,32.80000000000291]', NULL, 1768273735),
	(35824, 'Commande de fourniture d\'appâts', 'Un magasin de pêche a besoin de divers poissons communs comme appât. Aidez-les à réapprovisionner leur inventaire.', 'images/deliveries/bait_supply_order.png', '[{"display_name":"Ablette commune","name":"common_bleak","amount":10},{"display_name":"Achigan à petite bouche","name":"smallmouth_bass","amount":2}]', 184, NULL, '[-436.13,6154.93,31.48]', NULL, 1768273768);
INSERT INTO `fishing_simulator_available_dives` (`id`, `name`, `description`, `image`, `money_reward`, `item_reward`, `dive_location`, `progress`, `timestamp`) VALUES
	(35817, 'Le repaire du Kraken', 'Osez récupérer les trésors de l\'antre du mythique Kraken. Méfiez-vous de sa colère !', 'images/dives/kraken_lair.png', NULL, '{"item":"enchanted_jewel","display_name":"Enchanted Jewel","amount":3}', '[518.9099999999162,7300.8300000000749,-32.75]', NULL, 1768273495),
	(35818, 'Opération de sauvetage en haute mer', 'Récupérez une précieuse cargaison d\'un cargo coulé au fond de l\'océan.', 'images/dives/deep_sea_salvage.png', 2276, NULL, '[73.66,7413.73,-11.73]', NULL, 1768273527),
	(35819, 'Site d\'accident de météorite', 'Une météorite s\'est récemment écrasée dans l\'océan, créant un riche lit de minéraux rares.', 'images/dives/meteorite_crash.png', NULL, '{"display_name":"Meteorite Ore","item":"meteorite_ore","amount":5}', '[2197.730000000447,4334.789999999106,3.42000000000007]', NULL, 1768273610),
	(35820, 'La quête du plongeur de perles', 'Une plongée lucrative pour récolter les perles d\'un parc à huîtres dense, connue uniquement des plongeurs les plus âgés..', 'images/dives/pearl_diver.png', NULL, '{"item":"precious_pearls","display_name":"Precious Pearls","amount":20}', '[2149.9199999999257,-3034.3600000003355,-63.58999999999651]', NULL, 1768273615),
	(35821, 'Relique de la guerre froide', 'Récupérer le matériel d\'espionnage perdu dans un sous-marin coulé de la guerre froide.', 'images/dives/cold_war_relic.png', NULL, '{"display_name":"Spy Gadget","item":"spy_gadget","amount":1}', '[3672.28,5802.42,-52.19]', NULL, 1768273647),
	(35822, 'Anomalie du Triangle des Bermudes', 'Enquêtez sur une anomalie dans les profondeurs du Triangle des Bermudes. Attendez-vous à l\'inattendu.', 'images/dives/bermuda_triangle.png', NULL, '{"display_name":"Mystic Crystal","item":"mystic_crystal","amount":4}', '[-3462.179999999702,1863.220000000205,-54.80999999999767]', NULL, 1768273730),
	(35823, 'Photographie des récifs coralliens', 'Prenez de superbes photos du récif de corail pour un grand magazine. Ils paient bien pour la qualité !', 'images/dives/coral_reef_photography.png', 1521, NULL, '[715.0900000000838,4089.570000000298,25.66000000000349]', NULL, 1768273735),
	(35824, 'Explorateur de récifs', 'Explorez les récifs coralliens vibrants pour trouver des échantillons rares de vie marine pour les biologistes marins.', 'images/dives/reef_explorer.png', 1406, NULL, '[-1181.0347,6459.2319,-27.5255]', NULL, 1768273767);
