INSERT INTO `gmt_citizens_procedures` (`id`, `player`, `officer`, `title`, `text`, `important`, `time`) VALUES
	(1, 'char0:7dc3f59d32f97e30b411c97eca6052a274d9a7cb', 'char0:7dc3f59d32f97e30b411c97eca6052a274d9a7cb', 'a faire 3 fois par semaine', '- transfusion de fer 500mg/h pendant 2heure\n- transfusion de 3 culots hemoglobine pendant 2h\n\n\nsyndrome Vitiligo Albinien\nDecoloration morbide des cellules epipdermiques', 1, 1766706056),
	(2, 'char0:3e758eef33889a4b935038295e74501100f0e6d6', 'char0:7dc3f59d32f97e30b411c97eca6052a274d9a7cb', 'Blessure parr balle 26/12/2025', '- balle ressortit\n- desinfection\n- suture\n- nettoyage et bandage\n', 0, 1766766841),
	(10, 'char0:e5cde0a4dcf025e3c8bd48255c527529ddf37b2a', 'char0:7dc3f59d32f97e30b411c97eca6052a274d9a7cb', 'visite du 27/12', 'CAUSE : douleurs au ventre\nCONSEQUENCE : palpation / douleurs pancreatique\nEFFET : echographique abdominale / prise de sang et ponction pancreatique\nRésultats :\nLipase : 1 250 U/L (valeur normale < 60 U/L) ⬆️⬆️\n\nAmylase : 680 U/L (valeur normale 30–110 U/L) ⬆️\n\nCRP : 85 mg/L (normale < 5 mg/L) ⬆️\n\nLeucocytes : 15,8 G/L (normale 4–10 G/L) ⬆️\n\nASAT (TGO) : 62 U/L (légèrement élevée)\n\nALAT (TGP) : 70 U/L (légèrement élevée)\n\nBilirubine totale : Normale\n\nGlycémie : Légèrement élevée\nInterprétation  :\nLes résultats montrent une élévation marquée de la lipase et de l’amylase, associée à un *syndrome inflammatoire, compatible avec une atteinte pancréatique aiguë**. Un avis médical spécialisé est recommandé.\nConstantes :\nTA : 145/90 mmHg\nFC : 112 bpm\nTempérature : 38,4 °C\nSpO₂ : 97 % à l’air ambiant\n \nPRISE EN CHARGE MÉDICALE\nMise à jeun stricte\nPerfusion IV (remplissage + hydratation)\nAntalgiques puissants IV\nSurveillance journaliere ( pdt 7 jours)\nBilan étiologique en cours (alcool, lithiase, médicamenteux…)', 0, 1766874572),
	(11, 'char0:bc10125b58df7ee35ed811b1f06bb5c650a3c25f', 'char0:7dc3f59d32f97e30b411c97eca6052a274d9a7cb', 'visite du 26/12', 'cause : accident de scooter\nconsequence : bras cassé\neffet : operer / platrer, suivie medical intensif', 0, 1766874617),
	(12, 'char0:6237e5712c0e1dc54b6600afd42adf7f22b57ccf', 'char0:7dc3f59d32f97e30b411c97eca6052a274d9a7cb', 'visite du 26/12', 'CAUSE : douleurs dorsale suite a une chute\nCONSEQUENCE : vertebre deplacee\nEFFET : replacement de la vertebre + obligation de repos', 0, 1766876032),
	(13, 'char0:6237e5712c0e1dc54b6600afd42adf7f22b57ccf', 'char0:7dc3f59d32f97e30b411c97eca6052a274d9a7cb', 'visite du 26/12', 'CAUSE : accident de voiture\nCONSEQUENCES : fracture a la jambe droite\nEFFETS : operation + platre\n\nRESTRICTION : platre 24h', 0, 1766876043);
