INSERT INTO `p_dmv_schools` (`name`, `label`, `type`, `blipSprite`, `blipColor`, `mainCoords`, `theoryQuestions`, `practiceMap`, `start`, `tasks`) VALUES
	('car_dmv_school', 'DMV Car School', 'car', 351, 0, '{"y":-1378.680908203125,"x":241.32968139648438,"z":33.82964706420898}', '[{"image":"","question":"Quand le feu passe au vert, tu dois…","id":1756137284173,"options":[{"value":"Faire un burnout pour impressionner les passants","correct":false},{"value":"Démarrer calmement","correct":true},{"value":"Klaxonner pour faire avancer le monde","correct":false},{"value":"Sortir du véhicule pour danser","correct":false}]},{"image":"","question":"Si un citoyen traverse soudainement la route, tu…","id":1756137317350,"options":[{"value":"L’écrases, c’est son destin","correct":false},{"value":"Freines pour éviter la collision","correct":true},{"value":"Accélères pour voir s’il esquive","correct":false},{"value":"Fermes les yeux en espérant le meilleur","correct":false}]},{"image":"","question":"Sur autoroute, la limite raisonnable” est…","id":1756137330028,"options":[{"value":"300 km/h parce que t’as une Supersport","correct":false},{"value":"120–140 km/h","correct":true},{"value":"30 km/h pour admirer le paysage","correct":false},{"value":"5 km/h si tu tires une caravane","correct":false}]},{"image":"","question":"Quand la police te suit avec les gyrophares allumés, tu…","id":1756137351102,"options":[{"value":"T’arrêtes immédiatement","correct":true},{"value":"Lances une poursuite épique","correct":false},{"value":"Fais semblant de ne rien voir","correct":false},{"value":"Mets ta musique préférée","correct":false}]},{"image":"","question":"Avant de dépasser un véhicule, tu dois…","id":1756137372432,"options":[{"value":"Crier “YOLO” par la fenêtre","correct":false},{"value":"Vérifier rétros + clignotant","correct":true},{"value":"Sauter de la voiture pour éviter l’accident","correct":false},{"value":"Demander l’autorisation sur la radio","correct":false}]},{"image":"C’est normal, c’est du style","question":"Si ton véhicule fume noir…","id":1756137396893,"options":[{"value":"C’est normal, c’est du style","correct":false},{"valu